template <typename T>
class Storage {
    T item;
public:
    void store(T i) { item = i; }
};

// Explicit Instantiation Definition (Causes code generation here)
template class Storage<int>;
template Storage<bool>; // 'class' keyword is optional

template <typename T>
T process(T x) { return x * 2; }

// Explicit Instantiation Declaration (Prevents local generation)
extern template double process(double);

// Explicit Instantiation Definition
template long process(long);
